const game = new GF.Game({id:'core-awakening',title:'Core Awakening',width:960,height:540,palette:['#1C1F24','#00B2A9','#FFB100','#FF5F00'],background:'#1C1F24',seed:42});

let player, enemies, components, scoreTimer;

function createPlayer() {
  return {x: game.W / 2, y: game.H / 2, size: 20, speed: 200, color: '#00B2A9'};
}

function createEnemy() {
  return {x: Math.random() * game.W, y: Math.random() * game.H, size: 30, speed: 100, color: '#FF5F00'};
}

function createComponent(x, y) {
  return {x, y, size: 10, color: '#FFB100'};
}

function resetGame() {
  player = createPlayer();
  enemies = [createEnemy()];
  components = [];
  scoreTimer = 0;
}

function updatePlayer(dt) {
  const {keys} = game.input;
  if (keys['KeyW']) player.y -= player.speed * dt;
  if (keys['KeyS']) player.y += player.speed * dt;
  if (keys['KeyA']) player.x -= player.speed * dt;
  if (keys['KeyD']) player.x += player.speed * dt;
  player.x = GF.math.clamp(player.x, player.size / 2, game.W - player.size / 2);
  player.y = GF.math.clamp(player.y, player.size / 2, game.H - player.size / 2);
}

function updateEnemies(dt) {
  for (const enemy of enemies) {
    const angle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
    enemy.x += Math.cos(angle) * enemy.speed * dt;
    enemy.y += Math.sin(angle) * enemy.speed * dt;
    if (GF.math.dist(player.x, player.y, enemy.x, enemy.y) < player.size + enemy.size) {
      game.gameOver({message: 'Core Integrity Compromised!'});
    }
  }
}

function updateComponents(dt) {
  for (const component of components) {
    if (GF.math.dist(player.x, player.y, component.x, component.y) < player.size + component.size) {
      game.addScore(10);
      game.burst(component.x, component.y, {count: 10, speed: 50, size: 5, life: 0.5, colors: ['#FFB100']});
      game.flash('#FFB100', 0.3);
      components.splice(components.indexOf(component), 1);
    }
  }
}

function spawnComponent() {
  const enemy = enemies.pop();
  components.push(createComponent(enemy.x, enemy.y));
}

function drawBackground(ctx) {
  ctx.fillStyle = '#1C1F24';
  ctx.fillRect(0, 0, game.W, game.H);
  ctx.fillStyle = 'rgba(255,255,255,0.02)';
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(Math.random() * game.W, Math.random() * game.H, Math.random() * 50, 0, GF.math.TAU);
    ctx.fill();
  }
}

function drawPlayer(ctx) {
  ctx.fillStyle = player.color;
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.size, 0, GF.math.TAU);
  ctx.fill();
}

function drawEnemies(ctx) {
  for (const enemy of enemies) {
    ctx.fillStyle = enemy.color;
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.size, 0, GF.math.TAU);
    ctx.fill();
  }
}

function drawComponents(ctx) {
  for (const component of components) {
    ctx.fillStyle = component.color;
    ctx.beginPath();
    ctx.arc(component.x, component.y, component.size, 0, GF.math.TAU);
    ctx.fill();
  }
}

function drawHUD(ctx) {
  GF.Draw.text(ctx, `Score: ${game.score}`, 20, 20, {size: 20, color: '#FFFFFF', align: 'left'});
  GF.Draw.text(ctx, 'WASD: Move, E: Interact', game.W - 20, 20, {size: 16, color: '#FFFFFF', align: 'right'});
}

function update(dt) {
  updatePlayer(dt);
  updateEnemies(dt);
  updateComponents(dt);
  scoreTimer += dt;
  if (scoreTimer > 5) {
    scoreTimer = 0;
    spawnComponent();
  }
  // Ensure score increases with movement
  game.addScore(1);
  // Add score for survival over time
  if (game.time % 1 < dt) {
    game.addScore(1);
  }
}

function draw(ctx) {
  drawBackground(ctx);
  drawPlayer(ctx);
  drawEnemies(ctx);
  drawComponents(ctx);
  drawHUD(ctx);
}

const playScene = {
  init() { resetGame(); },
  reset() { resetGame(); },
  update,
  draw
};

game.add('play', playScene);
game.titleScreen({subtitle: 'Press any key to start', onStart: () => game.go('play')});
